    /**
     * Tests getting all Refunds.
     *
     * @return    Collection
     */
    public List<Refund> testGetAll() throws Throwable {
    LOGGER.info( "RefundTest:testGetAll() - Retrieving Collection of Refunds:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Refund : " );
    List<Refund> collection  = null;

    try {
        // call the static get method on the RefundService
        collection = service.getAllRefund();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Refund currEntity  = null;
            Iterator<Refund> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getRefundId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

